100	export function createScenarioStore() {
101	  return { scenarios: new Map(), clocks: new Map(), rules: new Map() };
102	}
103	
104	export function createApp(store = createScenarioStore()) {
105	  function isJsonContentType(request) {
106	    const contentType = request.headers["content-type"];
107	    if (typeof contentType !== "string") {
108	      return false;
109	    }
110	    const mediaType = contentType.split(";")[0].trim().toLowerCase();
111	    return mediaType === "application/json";
112	  }
113	
114	  function readBody(request) {
115	    return new Promise((resolve, reject) => {
116	      const chunks = [];
117	      let size = 0;
118	      request.on("data", chunk => {
119	        chunks.push(chunk);
120	        size += chunk.length;
121	      });
122	      request.on("end", () => resolve(Buffer.concat(chunks, size).toString("utf8")));
123	      request.on("error", reject);
124	    });
125	  }
126	
127	  async function readJsonObject(request, response) {
128	    if (!isJsonContentType(request)) {
129	      badRequest(response, "Content-Type must be application/json");
130	      return null;
131	    }
132	
133	    const raw = await readBody(request);
134	    if (raw.length === 0) {
135	      badRequest(response, "Request body must not be empty");
136	      return null;
137	    }
138	
139	    let body;
140	    try {
141	      body = JSON.parse(raw);
142	    } catch {
143	      badRequest(response, "Request body must be valid JSON");
144	      return null;
145	    }
146	
147	    if (!isPlainObject(body)) {
148	      badRequest(response, "Request body must be a JSON object");
149	      return null;
150	    }
151	
152	    return body;
153	  }
154	
155	  async function createScenario(request, response) {
156	    const body = await readJsonObject(request, response);
157	    if (body === null) {
158	      return;
159	    }
160	
161	    if (!isNonEmptyString(body.name)) {
162	      badRequest(response, "name must be a non-empty string");
163	      return;
164	    }
165	    if (body.description !== undefined && typeof body.description !== "string") {
166	      badRequest(response, "description must be a string");
167	      return;
168	    }
169	
170	    const scenario = {
171	      id: randomUUID(),
172	      name: body.name,
173	      description: body.description ?? "",
174	      revision: 0,
175	      events: [],
176	      createdAt: new Date().toISOString()
177	    };
178	    store.scenarios.set(scenario.id, scenario);
179	    sendJson(response, 201, scenario);
180	  }
181	
182	  async function createBranch(request, response, parentId) {
183	    const parent = store.scenarios.get(parentId);
184	    if (!parent) {
185	      notFound(response, "Scenario not found");
186	      return;
187	    }
188	
189	    const body = await readJsonObject(request, response);
190	    if (body === null) {
191	      return;
192	    }
193	
194	    if (!isNonEmptyString(body.name)) {
195	      badRequest(response, "name must be a non-empty string");
196	      return;
197	    }
198	    if (body.description !== undefined && typeof body.description !== "string") {
199	      badRequest(response, "description must be a string");
200	      return;
201	    }
202	    if (typeof body.fromRevision !== "number" || !Number.isInteger(body.fromRevision)) {
203	      badRequest(response, "fromRevision must be a decimal integer between 0 and the parent scenario's current revision");
204	      return;
205	    }
206	    if (body.fromRevision < 0 || body.fromRevision > parent.revision) {
207	      badRequest(response, "fromRevision must be between 0 and the parent scenario's current revision");
208	      return;
209	    }
210	
211	    const fromRevision = body.fromRevision;
212	    const branch = {
213	      id: randomUUID(),
214	      name: body.name,
215	      description: body.description ?? "",
216	      revision: fromRevision,
217	      events: structuredClone(parent.events.slice(0, fromRevision)),
218	      createdAt: new Date().toISOString(),
219	      parentScenarioId: parent.id,
220	      parentRevision: fromRevision
221	    };
222	    store.scenarios.set(branch.id, branch);
223	    sendJson(response, 201, branch);
224	  }
225	
226	  function listScenarios(response) {
227	    sendJson(response, 200, [...store.scenarios.values()]);
228	  }
229	
230	  function getScenario(response, id) {
231	    const scenario = store.scenarios.get(id);
232	    if (!scenario) {
233	      notFound(response, "Scenario not found");
234	      return;
235	    }
236	    sendJson(response, 200, scenario);
237	  }
238	
239	  async function appendEvent(request, response, id) {
240	    const scenario = store.scenarios.get(id);
241	    if (!scenario) {
242	      notFound(response, "Scenario not found");
243	      return;
244	    }
245	
246	    const body = await readJsonObject(request, response);
247	    if (body === null) {
248	      return;
249	    }
250	
251	    if (!isNonEmptyString(body.type)) {
252	      badRequest(response, "type must be a non-empty string");
253	      return;
254	    }
255	    if (body.payload !== undefined && !isPlainObject(body.payload)) {
256	      badRequest(response, "payload must be a JSON object");
257	      return;
258	    }
259	
260	    let occurredAt;
261	    if (body.occurredAt === undefined) {
262	      const clockTime = store.clocks.get(id);
263	      if (clockTime !== undefined) {
264	        const last = scenario.events[scenario.events.length - 1];
265	        if (last !== undefined && Date.parse(clockTime) < Date.parse(last.occurredAt)) {
266	          badRequest(response, "currentTime must not be earlier than the last event's occurredAt");
267	          return;
268	        }
269	      }
270	      occurredAt = clockTime ?? new Date().toISOString();
271	    } else {
272	      const parsed = parseUtcTimestamp(body.occurredAt);
273	      if (parsed === null) {
274	        badRequest(response, "occurredAt must be a UTC timestamp formatted as YYYY-MM-DDTHH:mm:ss.SSSZ");
275	        return;
276	      }
277	      const last = scenario.events[scenario.events.length - 1];
278	      if (last !== undefined && parsed.getTime() < Date.parse(last.occurredAt)) {
279	        badRequest(response, "occurredAt must not be earlier than the previous event's occurredAt");
280	        return;
281	      }
282	      occurredAt = body.occurredAt;
283	    }
284	
285	    const event = {
286	      id: randomUUID(),
287	      type: body.type,
288	      payload: body.payload ?? {},
289	      occurredAt,
290	      sequence: scenario.events.length + 1
291	    };
292	    scenario.events.push(event);
293	    scenario.revision += 1;
294	    sendJson(response, 201, event);
295	  }
296	
297	  async function setClock(request, response, id) {
298	    const scenario = store.scenarios.get(id);
299	    if (!scenario) {
300	      notFound(response, "Scenario not found");
301	      return;
302	    }
303	
304	    const body = await readJsonObject(request, response);
305	    if (body === null) {
306	      return;
307	    }
308	
309	    if (typeof body.currentTime !== "string") {
310	      badRequest(response, "currentTime must be a string formatted as YYYY-MM-DDTHH:mm:ss.SSSZ");
311	      return;
312	    }
313	    const parsed = parseUtcTimestamp(body.currentTime);
314	    if (parsed === null) {
315	      badRequest(response, "currentTime must be a UTC timestamp formatted as YYYY-MM-DDTHH:mm:ss.SSSZ");
316	      return;
317	    }
318	    const last = scenario.events[scenario.events.length - 1];
319	    if (last !== undefined && parsed.getTime() < Date.parse(last.occurredAt)) {
320	      badRequest(response, "currentTime must not be earlier than the last event's occurredAt");
321	      return;
322	    }
323	    const existing = store.clocks.get(id);
324	    if (existing !== undefined && parsed.getTime() < Date.parse(existing)) {
325	      badRequest(response, "currentTime must not be earlier than the current clock time");
326	      return;
327	    }
328	
329	    store.clocks.set(id, body.currentTime);
330	    sendJson(response, 200, { scenarioId: id, currentTime: body.currentTime });
331	  }
332	
333	  function getClock(response, id) {
334	    const scenario = store.scenarios.get(id);
335	    if (!scenario) {
336	      notFound(response, "Scenario not found");
337	      return;
338	    }
339	    sendJson(response, 200, { scenarioId: id, currentTime: store.clocks.get(id) ?? null });
340	  }
341	
342	  function validateRuleBody(body) {
343	    const allowedKeys = new Set(["name", "when", "then"]);
344	    for (const key of Object.keys(body)) {
345	      if (!allowedKeys.has(key)) {
346	        return { error: `Unknown field: ${key}` };
347	      }
348	    }
349	    if (!isNonEmptyString(body.name)) {
350	      return { error: "name must be a non-empty string" };
351	    }
352	    if (!isPlainObject(body.when)) {
353	      return { error: "when must be a JSON object" };
354	    }
355	    const whenKeys = Object.keys(body.when);
356	    if (whenKeys.length !== 1 || whenKeys[0] !== "type" || !isNonEmptyString(body.when.type)) {
357	      return { error: "when must contain exactly one non-empty string field: type" };
358	    }
359	    if (!isPlainObject(body.then)) {
360	      return { error: "then must be a JSON object" };
361	    }
362	    for (const key of Object.keys(body.then)) {
363	      if (key !== "type" && key !== "payload") {
364	        return { error: `Unknown field in then: ${key}` };
365	      }
366	    }
367	    if (!isNonEmptyString(body.then.type)) {
368	      return { error: "then.type must be a non-empty string" };
369	    }
370	    if (body.then.payload !== undefined && !isPlainObject(body.then.payload)) {
371	      return { error: "then.payload must be a JSON object" };
372	    }
373	    return { rule: body };
374	  }
375	
376	  async function createRule(request, response, id) {
377	    const scenario = store.scenarios.get(id);
378	    if (!scenario) {
379	      notFound(response, "Scenario not found");
380	      return;
381	    }
382	
383	    const body = await readJsonObject(request, response);
384	    if (body === null) {
385	      return;
386	    }
387	
388	    const { rule: validRule, error } = validateRuleBody(body);
389	    if (error !== undefined) {
390	      badRequest(response, error);
391	      return;
392	    }
393	
394	    const rule = {
395	      id: randomUUID(),
396	      name: validRule.name,
397	      when: { type: validRule.when.type },
398	      then:
399	        validRule.then.payload === undefined
400	          ? { type: validRule.then.type }
401	          : { type: validRule.then.type, payload: validRule.then.payload }
402	    };
403	
404	    let rules = store.rules.get(id);
405	    if (rules === undefined) {
406	      rules = [];
407	      store.rules.set(id, rules);
408	    }
409	    rules.push(rule);
410	    sendJson(response, 201, rule);
411	  }
412	
413	  function listRules(response, id) {
414	    const scenario = store.scenarios.get(id);
415	    if (!scenario) {
416	      notFound(response, "Scenario not found");
417	      return;
418	    }
419	    sendJson(response, 200, store.rules.get(id) ?? []);
420	  }
421	
422	  function replayScenario(response, id) {
423	    const scenario = store.scenarios.get(id);
424	    if (!scenario) {
425	      notFound(response, "Scenario not found");
426	      return;
427	    }
428	
429	    const rules = store.rules.get(id) ?? [];
430	    const results = [];
431	    for (const event of scenario.events) {
432	      for (const rule of rules) {
433	        if (rule.when.type !== event.type) {
434	          continue;
435	        }
436	        results.push({
437	          ruleId: rule.id,
438	          sourceSequence: event.sequence,
439	          type: rule.then.type,
440	          payload: rule.then.payload ?? {},
441	          occurredAt: event.occurredAt
442	        });
443	      }
444	    }
445	
446	    sendJson(response, 200, { revision: scenario.revision, results });
447	  }
448	
449	  function readSingleParam(url, name) {
450	    const values = url.searchParams.getAll(name);
451	    if (values.length > 1) {
452	      return { error: `${name} must appear at most once` };
453	    }
454	    return { value: values.length === 1 ? values[0] : undefined };
455	  }
456	
457	  function listEvents(response, id, url) {
458	    const scenario = store.scenarios.get(id);
459	    if (!scenario) {
460	      notFound(response, "Scenario not found");
461	      return;
462	    }
463	
464	    const paramKeys = new Set(url.searchParams.keys());
465	    for (const key of paramKeys) {
466	      if (!EVENT_QUERY_PARAMS.has(key)) {
467	        badRequest(response, `Unknown query parameter: ${key}`);
468	        return;
469	      }
470	    }
471	
472	    let fromIso = null;
473	    let toIso = null;
474	    let limit = DEFAULT_EVENTS_LIMIT;
475	    let cursorToken = undefined;
476	
477	    for (const name of ["from", "to", "limit", "cursor"]) {
478	      const result = readSingleParam(url, name);
479	      if (result.error) {
480	        badRequest(response, result.error);
481	        return;
482	      }
483	      const raw = result.value;
484	      if (raw === undefined) {
485	        continue;
486	      }
487	      if (raw === "") {
488	        badRequest(response, `${name} must not be empty`);
489	        return;
490	      }
491	      if (name === "from" || name === "to") {
492	        const date = parseUtcTimestamp(raw);
493	        if (date === null) {
494	          badRequest(response, `${name} must be a UTC timestamp formatted as YYYY-MM-DDTHH:mm:ss.SSSZ`);
495	          return;
496	        }
497	        if (name === "from") {
498	          fromIso = raw;
499	        } else {
500	          toIso = raw;
501	        }
502	      } else if (name === "limit") {
503	        if (!DECIMAL_INTEGER_PATTERN.test(raw) || raw.length > 9) {
504	          badRequest(response, "limit must be a decimal integer between 1 and 100");
505	          return;
506	        }
507	        limit = Number(raw);
508	        if (limit < 1 || limit > MAX_EVENTS_LIMIT) {
509	          badRequest(response, "limit must be a decimal integer between 1 and 100");
510	          return;
511	        }
512	      } else {
513	        cursorToken = raw;
514	      }
515	    }
516	
517	    if (fromIso !== null && toIso !== null && Date.parse(toIso) < Date.parse(fromIso)) {
518	      badRequest(response, "to must not be earlier than from");
519	      return;
520	    }
521	
522	    let cursor = null;
523	    if (cursorToken !== undefined) {
524	      cursor = decodeCursor(cursorToken);
525	      if (cursor === null) {
526	        badRequest(response, "cursor is invalid");
527	        return;
528	      }
529	      if (
530	        cursor.sid !== id
531	        || cursor.from !== fromIso
532	        || cursor.to !== toIso
533	        || cursor.limit !== limit
534	      ) {
535	        badRequest(response, "cursor does not match this query");
536	        return;
537	      }
538	      if (cursor.rev !== scenario.revision) {
539	        badRequest(response, "cursor is no longer valid because the scenario was modified");
540	        return;
541	      }
542	    }
543	
544	    const fromTime = fromIso === null ? null : Date.parse(fromIso);
545	    const toTime = toIso === null ? null : Date.parse(toIso);
546	    const afterSequence = cursor === null ? 0 : cursor.seq;
547	
548	    const page = [];
549	    let nextSequence = 0;
550	    for (const event of scenario.events) {
551	      if (event.sequence <= afterSequence) {
552	        continue;
553	      }
554	      const occurredAt = Date.parse(event.occurredAt);
555	      if (fromTime !== null && occurredAt < fromTime) {
556	        continue;
557	      }
558	      if (toTime !== null && occurredAt > toTime) {
559	        continue;
560	      }
561	      if (page.length === limit) {
562	        nextSequence = page[page.length - 1].sequence;
563	        break;
564	      }
565	      page.push(event);
566	    }
567	
568	    let nextCursor = null;
569	    if (nextSequence > 0) {
570	      nextCursor = encodeCursor({
571	        v: 1,
572	        sid: id,
573	        from: fromIso,
574	        to: toIso,
575	        limit,
576	        seq: nextSequence,
577	        rev: scenario.revision
578	      });
579	    }
580	
581	    sendJson(response, 200, {
582	      revision: scenario.revision,
583	      events: page,
584	      nextCursor
585	    });
586	  }
