588	  async function handleRequest(request, response) {
589	    const url = new URL(request.url ?? "/", "http://branchline.local");
590	    const segments = url.pathname.split("/");
591	
592	    try {
593	      if (request.method === "GET" && url.pathname === "/health") {
594	        sendJson(response, 200, {
595	          status: "ok",
596	          service: "branchline-core",
597	          version: "0.1.0"
598	        });
599	        return;
600	      }
601	
602	      if (segments.length === 2 && segments[1] === "scenarios") {
603	        if (request.method === "POST") {
604	          await createScenario(request, response);
605	          return;
606	        }
607	        if (request.method === "GET") {
608	          listScenarios(response);
609	          return;
610	        }
611	      } else if (segments.length === 3 && segments[1] === "scenarios") {
612	        const id = decodeURIComponent(segments[2]);
613	        if (request.method === "GET") {
614	          getScenario(response, id);
615	          return;
616	        }
617	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "branches") {
618	        const id = decodeURIComponent(segments[2]);
619	        if (request.method === "POST") {
620	          await createBranch(request, response, id);
621	          return;
622	        }
623	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "clock") {
624	        const id = decodeURIComponent(segments[2]);
625	        if (request.method === "POST") {
626	          await setClock(request, response, id);
627	          return;
628	        }
629	        if (request.method === "GET") {
630	          getClock(response, id);
631	          return;
632	        }
633	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "rules") {
634	        const id = decodeURIComponent(segments[2]);
635	        if (request.method === "POST") {
636	          await createRule(request, response, id);
637	          return;
638	        }
639	        if (request.method === "GET") {
640	          listRules(response, id);
641	          return;
642	        }
643	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "replay") {
644	        const id = decodeURIComponent(segments[2]);
645	        if (request.method === "GET") {
646	          replayScenario(response, id);
647	          return;
648	        }
649	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "events") {
650	        const id = decodeURIComponent(segments[2]);
651	        if (request.method === "POST") {
652	          await appendEvent(request, response, id);
653	          return;
654	        }
