      eventType: "alpha",
      occurredAt: stamp,
      rule: { name: "A", when: { type: "alpha" }, then: { type: "same" } }
    });
    const right = await createScenarioWithRule(baseUrl, "Right", {
      eventType: "alpha",
      occurredAt: stamp,
      rule: { name: "B", when: { type: "alpha" }, then: { type: "same" } }
